using System;using System.Collections;using System.Collections.Generic;using System.Security.Cryptography;using System.Text;using System.Runtime.CompilerServices;using System.Diagnostics;
class ScriptContextCacheContracts {
 static int checks,hashes,reads;static void Need(bool value,string reason){checks++;if(!value)throw new Exception(reason);}
 static string Hash(string code){hashes++;using(var h=SHA256.Create())return BitConverter.ToString(h.ComputeHash(Encoding.UTF8.GetBytes(code))).Replace("-","").ToLowerInvariant();}
 static int Statement(object command){reads++;return (int)command;}
 static ScriptContextCache Cache(){return new ScriptContextCache(Hash,Statement);}
 static ArrayList Commands(int count){var result=new ArrayList(count);for(int i=0;i<count;i++)result.Add(i%7==0?291:i%11==0?292:5);return result;}
 [MethodImpl(MethodImplOptions.NoInlining)]static WeakReference WeakSource(ScriptContextCache cache){var code=new string('x',1234);cache.Hash(code);return new WeakReference(code);}
 [MethodImpl(MethodImplOptions.NoInlining)]static WeakReference WeakCommands(ScriptContextCache cache){var commands=Commands(10);cache.Ordinals(commands,"weak");return new WeakReference(commands);}
 static void Benchmark(){
  string[] codes=new string[4];ArrayList[] lists=new ArrayList[4];for(int i=0;i<4;i++){codes[i]=new string((char)('a'+i),8192);lists[i]=Commands(4096);}const int iterations=1024;string last=null,value=null;IList lastCommands=null;int[] previous=null;long checksum=0;
  hashes=reads=0;var watch=Stopwatch.StartNew();for(int n=0;n<iterations;n++){int j=n%4;if(codes[j]!=last){last=codes[j];value=Hash(last);}if(!Object.ReferenceEquals(lastCommands,lists[j])){lastCommands=lists[j];previous=new int[lists[j].Count];int ordinal=-1;for(int k=0;k<previous.Length;k++){int s=Statement(lists[j][k]);if(s==291||s==292)ordinal++;previous[k]=(s==291||s==292)?ordinal:-1;}}checksum+=value.Length+previous[0];}watch.Stop();int oldHashes=hashes,oldReads=reads;double oldMs=watch.Elapsed.TotalMilliseconds;
  var cache=Cache();hashes=reads=0;long actual=0;watch.Restart();for(int n=0;n<iterations;n++){int j=n%4;actual+=cache.Hash(codes[j]).Length+cache.Ordinals(lists[j],"source-"+j)[0];}watch.Stop();
  Need(actual==checksum,"alternating workload result");Need(oldHashes==iterations&&hashes==4,"alternating source hashes reduced");Need(oldReads==iterations*4096&&reads==4*4096,"alternating ordinal rebuilds reduced");Need(cache.RetainedOrdinals==16384,"bounded workload retention");
  Console.WriteLine("WORKLOAD 4 scripts x8192 chars, 4096 commands, 1024 alternating outputs: hashes "+oldHashes+" -> "+hashes+", command visits "+oldReads+" -> "+reads+", elapsed_ms "+oldMs.ToString("F3")+" -> "+watch.Elapsed.TotalMilliseconds.ToString("F3")+"; retained ordinals="+cache.RetainedOrdinals+" (synthetic host workload, not game FPS)");
 }
 static void Main(){var cache=Cache();string a=new string('a',40),b=new string('b',40);hashes=0;string ah=cache.Hash(a),bh=cache.Hash(b);Need(cache.Hash(a)==ah&&cache.Hash(b)==bh&&hashes==2,"multiple immutable sources reuse hashes");Need(ah!=bh,"different code never aliases");Need(cache.Hash(new string('a',40))==ah&&hashes==3,"equal text in new source instance remains exact");Need(cache.Hash(null)==null,"missing source remains unbound");
  var one=new ArrayList{5,291,0,292};var two=new ArrayList{291,0,292};reads=0;var x=cache.Ordinals(one,ah);var y=cache.Ordinals(two,bh);Need(x[0]==-1&&x[1]==0&&x[2]==-1&&x[3]==1,"original output ordinals");Need(Object.ReferenceEquals(cache.Ordinals(one,ah),x)&&Object.ReferenceEquals(cache.Ordinals(two,bh),y)&&reads==7,"alternating command lists reuse maps");
  one[0]=291;var edit=cache.Ordinals(one,"edited-source");Need(!Object.ReferenceEquals(edit,x)&&edit[3]==2,"source revision invalidates same-length command list");one.Add(292);Need(cache.Ordinals(one,"edited-source").Length==5,"command count invalidates map");var replacement=new ArrayList(one);Need(!Object.ReferenceEquals(cache.Ordinals(replacement,"edited-source"),cache.Ordinals(one,"edited-source")),"replacement command identity isolated");
  cache.Clear();Need(cache.RetainedOrdinals==0,"scene clear releases maps");int before=hashes;cache.Hash(a);Need(hashes==before+1,"scene clear invalidates hash entries");
  for(int n=0;n<20;n++){cache.Hash(new string((char)(100+n),20));cache.Ordinals(Commands(5000),"large-"+n);Need(cache.RetainedOrdinals<=ScriptContextCache.OrdinalBudget,"ordinal budget");}
  var bounded=Cache();var owners=new List<ArrayList>();for(int n=0;n<8;n++){owners.Add(Commands(5000));bounded.Ordinals(owners[n],"large-"+n);}Need(bounded.RetainedOrdinals==30000,"live owners obey aggregate budget");int visits=reads;bounded.Ordinals(owners[7],"large-7");Need(reads==visits,"recent ordinal map survives budget eviction");bounded.Ordinals(owners[0],"large-0");Need(reads==visits+5000,"old ordinal map evicted and rebuilt");
  var lru=Cache();var sources=new List<string>();for(int n=0;n<16;n++){sources.Add(new string((char)(200+n),31));lru.Hash(sources[n]);}lru.Hash(sources[0]);lru.Hash(new string('z',31));int hashed=hashes;lru.Hash(sources[0]);Need(hashes==hashed,"recent source survives capacity eviction");lru.Hash(sources[1]);Need(hashes==hashed+1,"oldest source is evicted");
  var failed=Cache();var bad=new ArrayList{291,"invalid",292};for(int n=0;n<2;n++){bool threw=false;try{failed.Ordinals(bad,"failure");}catch(InvalidCastException){threw=true;}Need(threw&&failed.RetainedOrdinals==0,"failed ordinal build is never published");}bad[1]=5;Need(failed.Ordinals(bad,"failure")[2]==1,"retry after failed ordinal build");
  int attempts=0;var broken=new ScriptContextCache(code=>{attempts++;throw new InvalidOperationException();},Statement);for(int n=0;n<2;n++)try{broken.Hash(a);}catch(InvalidOperationException){}Need(attempts==2,"failed hash is never published");
  bool rejected=false;try{cache.Ordinals(Commands(ScriptContextCache.MaxCommands+1),ah);}catch(ArgumentOutOfRangeException){rejected=true;}Need(rejected,"original command limit");
  var weakSource=WeakSource(cache);var weakCommands=WeakCommands(cache);for(int n=0;n<3;n++){GC.Collect();GC.WaitForPendingFinalizers();}Need(!weakSource.IsAlive&&!weakCommands.IsAlive,"cache does not retain source or command graph");
  Benchmark();Console.WriteLine("PASS "+checks+" script cache contracts");
 }
}
